 if(o&&(o.appointmentId||blockedReason(s,o)||['booked','completed','paused'].includes(o.status)))return wrap(head(c,'这条机会已有安排','避免重复预约','radar')+notice(E(c,blockedReason(s,o)||'请查看现有预约；暂停或完成的机会不能创建重复预约。'))+(o.appointmentId?nav(c,'查看关联预约','business-appointment',o.appointmentId,'primary'):nav(c,'查看机会详情','opportunity',o.id,'secondary')));
 const pets=A(s,'pets').filter(p=>!p.deceased&&(!o||p.id===o.petId)),pid=o?.petId||b.petId||pets[0]?.id,p=pet(s,pid),cat=p.species?p.species==='cat':/猫|布偶|暹罗|英短|美短/.test(p.breed),services=A(s,'services').filter(x=>x.enabled!==false&&(!o||x.id===o.serviceId)&&(cat?/猫|cat/.test(x.species):/犬|狗|dog/.test(x.species))),requestedSid=o?.serviceId||b.serviceId,sid=services.some(x=>x.id===requestedSid)?requestedSid:services[0]?.id,sv=service(s,sid),emps=A(s,'employees').filter(e=>e.active!==false&&(e.skills||[]).includes(sid)&&(sv.employeeIds||[]).includes(e.id)),eid=emps.some(e=>e.id===b.employeeId)?b.employeeId:emps.some(e=>e.id===o?.employeeId)?o.employeeId:emps[0]?.id,date=b.date||s.today,list=slots(s,date,eid,sid),selectedTime=list.some(x=>x.time===b.time&&!x.blocked)?b.time:list.find(x=>!x.blocked)?.time||'';
 if(!pets.length||!services.length)return wrap(empty(c,'预约还缺少基础资料','请先录入顾客宠物，并开放至少一项服务。',nav(c,'去客户管理','customers')));
